async run(
  canvasId: string,
  canvasElement: HTMLCanvasElement | null,
): Promise<SceneFromState | null> {
  if (!(canvasElement instanceof HTMLCanvasElement)) return null;
  const introConfig = readWorksTheatreConfig();
  if (introConfig.steps.length === 0) return null;

  await ensureWorksTheatreRuntimeReady();
  if (this._disposed) return null;

  const firstStep = introConfig.steps[0] ?? null;
  const initialState = WorksSceneDefinition.createInitialState(
    readWorksTheatreStepState(firstStep, 0),
  );
  const engine = createWorksEngine(canvasId, canvasElement);
  if (!engine.init()) return null;
  this._engine = engine;

  this._objectSetup = new ObjectSetup();
  const config = WorksSceneDefinition.createIntroPageConfig(canvasId, initialState);
  await this._objectSetup.init(engine, config);
  if (this._disposed || this._engine !== engine) return null;

  engine.setState(initialState);
  engine.start(() => undefined, () => undefined);

  for (const step of introConfig.steps) {
    if (this._disposed || this._engine !== engine) return null;
    await this._playStep(step);
  }

  const lastStep = introConfig.steps[introConfig.steps.length - 1] ?? null;
  return readWorksTheatreStepState(lastStep, 1);
}

dispose(): void {
  this._disposed = true;
  if (this._frameId !== null) {
    FrameScheduler.cancel(this._frameId);
    this._frameId = null;
  }
  this._objectSetup?.dispose();
  this._objectSetup = null;
  this._engine?.dispose();
  this._engine = null;
}

private _playStep(step: WorksIntroSheetStepConfig): Promise<void> {
  return new Promise<void>((resolve) => {
    const engine = this._engine;
    if (!engine || this._disposed) {
      resolve();
      return;
    }
    const startedAt = resolveTimestamp();
    const durationMs = Math.max(1, step.durationMs);
    const tick = (): void => {
      if (this._disposed || this._engine !== engine) {
        this._frameId = null;

