1	import worksIntroState from "../../../../json/works.json";
2	import { MAIN_SCENE_LIGHT_STATE_DEFAULTS } from "../../../config/scene-light.config.js";
3	import { sceneLights } from "../../../core/setup.js";
4	import { TheatreProjectSession } from "../../../lib/theatre/TheatreProjectSession.js";
5	import { TheatreSheetSession } from "../../../lib/theatre/TheatreSheetSession.js";
6	import type { SceneFromState } from "../../../types/core.types.js";
7	import type { SceneLightsStateSnapshot } from "../../../types/object.types.js";
8	import type { TheatreProjectPort, TheatreSequencePort } from "../../../types/theatre.types.js";
9	import type {
10	  WorksIntroSheetStepConfig,
11	  WorksIntroTheatreConfig,
12	  WorksTheatrePlaybackRange,
13	  WorksTheatreSnapshot,
14	  WorksTheatreSheetId,
15	  WorksTheatreValue,
16	} from "../../../types/work.types.js";
17	import { Helpers } from "../../../utils/Helpers.js";
18	import {
19	  readWorksTheatreConfigSource,
20	  WORKS_INTRO_TRACK_DEBUG_NAMES,
21	  WORKS_THEATRE_OBJECT_ID,
22	  WORKS_THEATRE_PROJECT_ID,
23	  WORKS_THEATRE_SHEET_IDS,
24	} from "./WorksTheatreConfig.js";
25	
26	function sanitizeWorksTheatreState(
27	  state: Record<string, unknown> | null,
28	): Record<string, unknown> | null {
29	  if (!state) return null;
30	  const sheetsByIdValue = state.sheetsById;
31	  if (
32	    sheetsByIdValue == null ||
33	    typeof sheetsByIdValue !== "object" ||
34	    Array.isArray(sheetsByIdValue)
35	  ) {
36	    return state;
37	  }
38	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
39	  const nextSheetsById: Record<string, unknown> = {};
40	  WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
41	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
42	    nextSheetsById[sheetId] = sheetsById[sheetId];
43	  });
44	  return {
45	    ...state,
46	    sheetsById: nextSheetsById,
47	  };
48	}
49	
50	function hasWorksTheatreSheets(
51	  state: Record<string, unknown> | null,
52	): state is Record<string, unknown> {
53	  if (!state) return false;
54	  const sheetsByIdValue = state.sheetsById;
55	  if (
56	    sheetsByIdValue == null ||
57	    typeof sheetsByIdValue !== "object" ||
58	    Array.isArray(sheetsByIdValue)
59	  ) {
60	    return false;
61	  }
62	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
63	  return WORKS_THEATRE_SHEET_IDS.every((sheetId) =>
64	    Object.prototype.hasOwnProperty.call(sheetsById, sheetId),
65	  );
66	}
67	
68	function readWorksTheatrePrimaryState(): Record<string, unknown> | null {
69	  const parsedState = worksIntroState as Record<string, unknown>;
70	  const sanitizedState = sanitizeWorksTheatreState(parsedState);
71	  if (!hasWorksTheatreSheets(sanitizedState)) return null;
72	  return sanitizedState;
73	}
74	
75	function readWorksTheatreStateSource(): Record<string, unknown> | null {
76	  return readWorksTheatrePrimaryState();
77	}
78	
79	function readRecord(value: unknown): Record<string, unknown> | null {
80	  if (value == null || typeof value !== "object" || Array.isArray(value)) {
81	    return null;
82	  }
83	  return value as Record<string, unknown>;
84	}
85	
86	function readNumber(value: unknown, fallback: number): number {
87	  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
88	  return value;
89	}
90	
91	function cloneDefaultWorksSceneLightsState(): SceneLightsStateSnapshot {
92	  return {
93	    ...MAIN_SCENE_LIGHT_STATE_DEFAULTS,
94	    ground: {
95	      position: { ...MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.position },
96	      rotation: { ...MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.rotation },
97	      scale: { ...MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.scale },
98	      visible: MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.visible,
99	    },
100	  };
101	}
102	
103	export function normalizeWorksSceneLightsState(
104	  value: unknown,
105	): SceneLightsStateSnapshot {
106	  const defaults = cloneDefaultWorksSceneLightsState();
107	  const sceneLightsState = readRecord(value);
108	  const groundState = readRecord(sceneLightsState?.ground);
109	  const groundPosition = readRecord(groundState?.position);
110	  const groundRotation = readRecord(groundState?.rotation);
111	  const groundScale = readRecord(groundState?.scale);
112	
113	  return {
114	    visible:
115	      typeof sceneLightsState?.visible === "boolean"
116	        ? sceneLightsState.visible
117	        : defaults.visible,
118	    intensity: readNumber(
119	      sceneLightsState?.intensity,
120	      defaults.intensity,
121	    ),
122	    flightProgress: readNumber(
123	      sceneLightsState?.flightProgress,
124	      defaults.flightProgress,
125	    ),
126	    groundLight: readNumber(
127	      sceneLightsState?.groundLight,
128	      defaults.groundLight,
129	    ),
130	    rocketFillLight: readNumber(
131	      sceneLightsState?.rocketFillLight,
132	      defaults.rocketFillLight,
133	    ),
134	    rocketRimLightLeft: readNumber(
135	      sceneLightsState?.rocketRimLightLeft,
136	      defaults.rocketRimLightLeft,
137	    ),
138	    rocketRimLightRight: readNumber(
139	      sceneLightsState?.rocketRimLightRight,
140	      defaults.rocketRimLightRight,
141	    ),
142	    ground: {
143	      position: {
144	        x: readNumber(groundPosition?.x, defaults.ground.position.x),
145	        y: readNumber(groundPosition?.y, defaults.ground.position.y),
146	        z: readNumber(groundPosition?.z, defaults.ground.position.z),
147	      },
148	      rotation: {
149	        x: readNumber(groundRotation?.x, defaults.ground.rotation.x),
150	        y: readNumber(groundRotation?.y, defaults.ground.rotation.y),
151	        z: readNumber(groundRotation?.z, defaults.ground.rotation.z),
152	      },
153	      scale: {
154	        x: readNumber(groundScale?.x, defaults.ground.scale.x),
155	        y: readNumber(groundScale?.y, defaults.ground.scale.y),
156	        z: readNumber(groundScale?.z, defaults.ground.scale.z),
157	      },
158	      visible:
159	        typeof groundState?.visible === "boolean"
160	          ? groundState.visible
161	          : defaults.ground.visible,
162	    },
163	  };
164	}
165	
166	function createDefaultWorksTheatreValue(): WorksTheatreSnapshot {
167	  return {
