import { EnvSetup } from "../../app/EnvSetup.js";
import type {
  TheatreAuthorControlRenderOptions,
  TheatreAuthorSelectRenderOptions,
  TheatreDownloadFileOptions,
  TheatreScrubPort,
  TheatreSelectionItemPort,
  TheatreStudioModulePort,
} from "../../types/theatre.types.js";
import type { DomStyleEntries } from "../../types/runtime.types.js";
import { THEATRE_AUTHOR_UI } from "../../config/component.config.js";

const PERSISTENCE_KEY_PREFIX = "page-theatre-studio-v2";
const THEATRE_STUDIO_ROOT_ID = "theatrejs-studio-root";
const LENIS_PREVENT_ATTRIBUTE_NAMES = [
  "data-lenis-prevent",
  "data-lenis-prevent-wheel",
  "data-lenis-prevent-touch",
] as const;

export class TheatreStudioService {
  private static _initialized = false;
  private static _initializedPersistenceKey: string | null = null;
  private static _studio: TheatreStudioModulePort | null = null;
  private static _listenersBound = false;
  private static _markAttempts = 0;
  private static _markFrameId: number | null = null;
  private static readonly _onWheelCapture = (event: Event) => {
    if (!TheatreStudioService._isEventInsideStudio(event)) return;
    event.stopPropagation();
  };
  private static readonly _onTouchMoveCapture = (event: Event) => {
    if (!TheatreStudioService._isEventInsideStudio(event)) return;
    event.stopPropagation();
  };

  static async ensureReady(pageType?: string): Promise<void> {
    const persistenceKey =
      TheatreStudioService._resolvePersistenceKey(pageType);
    if (
      TheatreStudioService._initialized &&
      TheatreStudioService._initializedPersistenceKey === persistenceKey
    ) {
      return;
    }
    if (
      TheatreStudioService._initialized &&
      TheatreStudioService._initializedPersistenceKey !== persistenceKey
    ) {
      return;
    }
    const studio = await TheatreStudioService._loadStudio();
