file.content:
@use "../abstract" as *;

body.has-custom-cursor {
  cursor: none;
}

.no-custom-cursor {
  position: fixed;
  left: 0;
  top: 0;
  width: fluid(8, 12);
  height: fluid(8, 12);
  transform: translate(-50%, -50%) scale(1);
  transform-origin: center center;
  pointer-events: none;
  z-index: var(--z-index-custom-cursor);
  background: #fff;
  mix-blend-mode: difference;
  will-change: transform, left, top;
  transition: transform 0.18s var(--ease-smooth);

  &--interactive {
    transform: translate(-50%, -50%) scale(1.12);
  }

  &--reduced-motion {
    transition: none;
  }
  @include mq(md) {
    display: none;
  }
}

