import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { pageAbout, pageContact, pageMain } from "../core/setup.js";
import type { Engine } from "../core/Engine.js";
import { EnvSetup } from "../app/EnvSetup.js";
import type { PageConfig } from "../types/core.types.js";
import type {
  TheatreAuthorBridgeHooks,
  TheatreAuthorMode,
  TheatreBridgePort,
} from "../types/theatre.types.js";
import type { TheatreBridgeFactory } from "../types/runtime.types.js";

const THEATRE_QUERY_KEY = "theatre";
const THEATRE_QUERY_ENABLED = "1";

const THEATRE_BRIDGE_FACTORIES: Readonly<
  Partial<Record<string, TheatreBridgeFactory>>
> = {
  [pageAbout]: async (engine, controls, hooks) => {
    const { AboutTheatreBridge } =
      await import("../pages/about/theatre/AboutTheatreBridge.js");
    return AboutTheatreBridge.create(engine, controls, hooks);
  },
  [pageMain]: async (engine, controls, hooks) => {
    const { MainTheatreBridge } =
      await import("../pages/main/theatre/MainTheatreBridge.js");
    return MainTheatreBridge.create(engine, controls, hooks);
  },
  [pageContact]: async (engine, controls, hooks) => {
    const { ContactTheatreBridge } =
      await import("../pages/contact/theatre/ContactTheatreBridge.js");
    return ContactTheatreBridge.create(engine, controls, hooks);
  },
};

export class AppOrbitRuntime {
  private _controls: OrbitControls | null = null;
  private _theatreBridge: TheatreBridgePort | null = null;
  private _mode: TheatreAuthorMode = "scroll";
  private _appliedMode: TheatreAuthorMode | null = null;
  private _paused = false;

  async init(
    engine: Engine,
    pageConfig: PageConfig,
    onAuthorMode: () => void,
    onScrollMode: () => void,
  ): Promise<void> {
    this.dispose();

    if (!pageConfig.orbitControls?.enabled) return;
    const renderer = engine.getRenderer() as {
      domElement?: HTMLCanvasElement;
    } | null;
    const domElement = renderer?.domElement;
    if (!domElement) return;

    const controls = new OrbitControls(engine.getCamera(), domElement);
    controls.target = engine.getCameraTarget().position;
    controls.enableDamping = pageConfig.orbitControls.enableDamping ?? true;
    if (typeof pageConfig.orbitControls.dampingFactor === "number") {
      controls.dampingFactor = pageConfig.orbitControls.dampingFactor;
    }
    if (typeof pageConfig.orbitControls.rotateSpeed === "number") {
      controls.rotateSpeed = pageConfig.orbitControls.rotateSpeed;
    }
    if (typeof pageConfig.orbitControls.zoomSpeed === "number") {
      controls.zoomSpeed = pageConfig.orbitControls.zoomSpeed;
    }
    if (typeof pageConfig.orbitControls.panSpeed === "number") {
      controls.panSpeed = pageConfig.orbitControls.panSpeed;
    }
    if (typeof pageConfig.orbitControls.minDistance === "number") {
      controls.minDistance = pageConfig.orbitControls.minDistance;
    }
    if (typeof pageConfig.orbitControls.maxDistance === "number") {
      controls.maxDistance = pageConfig.orbitControls.maxDistance;
    }
    if (typeof pageConfig.orbitControls.minPolarAngle === "number") {
      controls.minPolarAngle = pageConfig.orbitControls.minPolarAngle;
    }
    if (typeof pageConfig.orbitControls.maxPolarAngle === "number") {
      controls.maxPolarAngle = pageConfig.orbitControls.maxPolarAngle;
    }
    controls.update();
    this._controls = controls;

    const pageType = pageConfig.pageId;
    if (!THEATRE_BRIDGE_FACTORIES[pageType]) return;

    const theatreBridge = await this._createTheatreBridge(
      pageType,
      engine,
      controls,
      {
        onModeChange: (mode) => {
          this._mode = mode;
          this._syncMode(onAuthorMode, onScrollMode);
        },
        onPlaybackChange: () => {
          this._syncMode(onAuthorMode, onScrollMode);
        },
      },
    );
    this._theatreBridge = theatreBridge;
    this._mode = theatreBridge ? "author" : "scroll";
    this._syncMode(onAuthorMode, onScrollMode);
  }

  update(): void {
    if (!this._controls) return;
    if (this._paused) return;
    if (this._mode === "author" && this._theatreBridge) return;
    this._controls.update();
  }

  pause(): void {
    this._paused = true;
  }

  resume(engine: Engine): void {
    const controls = this._controls;
    if (!controls) return;
    this._paused = false;
    controls.target.copy(engine.getCameraTarget().position);
    controls.update();
  }

  dispose(): void {
    this._theatreBridge?.dispose();
    this._theatreBridge = null;
    this._controls?.dispose();
    this._controls = null;
    this._mode = "scroll";
    this._appliedMode = null;
    this._paused = false;
  }

  private _syncMode(onAuthorMode: () => void, onScrollMode: () => void): void {
    const controls = this._controls;
    if (!controls) return;

    if (this._mode !== this._appliedMode) {
      if (this._mode === "author") onAuthorMode();
      else onScrollMode();
      this._appliedMode = this._mode;
    }

    controls.enabled = this._mode === "author";
  }

  private async _createTheatreBridge(
    pageType: string,
    engine: Engine,
    controls: OrbitControls,
    hooks: TheatreAuthorBridgeHooks,
  ): Promise<TheatreBridgePort | null> {
    if (
      !EnvSetup.hasQueryFlag(THEATRE_QUERY_KEY, THEATRE_QUERY_ENABLED)
    ) {
      return null;
    }
    const factory = THEATRE_BRIDGE_FACTORIES[pageType];
    if (!factory) return null;
    return factory(engine, controls, hooks);
  }
}

